"      <label class=\"fld\"><span>High contrast</span><span class=\"sw\"><input type=\"checkbox\" name=\"contrast\"><i></i></span></label>\n"
"      <label class=\"fld\"><span>Animations</span><span class=\"sw\"><input type=\"checkbox\" name=\"animations\"><i></i></span></label>\n"
"      <label class=\"fld\"><span>Speed-test download limit</span><select name=\"speed_mb\"><option value=\"1\">1 MB</option><option value=\"5\">5 MB</option><option value=\"10\">10 MB</option><option value=\"20\">20 MB</option></select></label>\n"
"      <label class=\"fld\"><span>Screen brightness</span><input type=\"range\" name=\"bright\" min=\"5\" max=\"100\" step=\"5\"><output id=\"o-bright\"></output></label>\n"
"      <label class=\"fld\"><span>Screen off after</span><select name=\"sleep\"><option value=\"0\">Never</option><option value=\"30\">30 seconds</option><option value=\"60\">1 minute</option><option value=\"300\">5 minutes</option><option value=\"600\">10 minutes</option></select></label>\n"
"      <label class=\"fld\"><span>Temperature units</span><select name=\"units_c\"><option value=\"0\">Fahrenheit</option><option value=\"1\">Celsius</option></select></label>\n"
"      <label class=\"fld\"><span>Run AutoTest when plugged in</span><span class=\"sw\"><input type=\"checkbox\" name=\"autotest\"><i></i></span></label>\n"
"      <label class=\"fld\"><span>Battery fitted</span><span class=\"sw\"><input type=\"checkbox\" name=\"battery\"><i></i></span></label>\n"
"      <label class=\"fld\"><span>Port blink length</span><select name=\"blink\"><option value=\"6\">6 s</option><option value=\"12\">12 s</option><option value=\"20\">20 s</option><option value=\"30\">30 s</option></select></label>\n"
"      <label class=\"fld\"><span>Time zone</span><select name=\"tz\">\n"
"        <option value=\"EST5EDT,M3.2.0,M11.1.0\">Eastern</option><option value=\"CST6CDT,M3.2.0,M11.1.0\">Central</option>\n"
"        <option value=\"MST7MDT,M3.2.0,M11.1.0\">Mountain</option><option value=\"MST7\">Arizona</option>\n"
"        <option value=\"PST8PDT,M3.2.0,M11.1.0\">Pacific</option><option value=\"AKST9AKDT,M3.2.0,M11.1.0\">Alaska</option>\n"
"        <option value=\"HST10\">Hawaii</option><option value=\"UTC0\">UTC</option></select></label>\n"
"\n"
"      <div class=\"sub-h\">Ethernet address</div>\n"
"      <label class=\"fld\"><span>Use a static IP instead of DHCP</span><span class=\"sw\"><input type=\"checkbox\" name=\"static\" id=\"s-static\"><i></i></span></label>\n"
"      <div id=\"s-fields\">\n"
"        <label class=\"fld stack\"><span>IP address</span><input type=\"text\" name=\"s_ip\" placeholder=\"10.0.0.50\" inputmode=\"decimal\"></label>\n"
"        <label class=\"fld stack\"><span>Subnet mask</span><input type=\"text\" name=\"s_mask\" placeholder=\"255.255.255.0\" inputmode=\"decimal\"></label>\n"
"        <label class=\"fld stack\"><span>Gateway</span><input type=\"text\" name=\"s_gw\" placeholder=\"10.0.0.1\" inputmode=\"decimal\"></label>\n"
"        <label class=\"fld stack\"><span>DNS server</span><input type=\"text\" name=\"s_dns\" placeholder=\"8.8.8.8\" inputmode=\"decimal\"></label>\n"
"      </div>\n"
"\n"
"      <div class=\"sub-h\">Hotspot and hub</div>\n"
"      <label class=\"fld\"><span>Phone hotspot</span><span class=\"sw\"><input type=\"checkbox\" name=\"hotspot\"><i></i></span></label>\n"
"      <label class=\"fld stack\"><span>Hotspot password (8+ characters)</span><input type=\"password\" name=\"ap_pass\"></label>\n"
"      <label class=\"fld stack\"><span>SENTRY hub MQTT address</span><input type=\"text\" name=\"mqtt\" placeholder=\"mqtt://10.0.0.5:1883\"></label>\n"
"      <label class=\"fld stack\"><span>OpenWeatherMap API key (weather on the home screen)</span><input type=\"text\" name=\"owm\" placeholder=\"leave blank for no weather\"></label>\n"
"      <label class=\"fld stack\"><span>Link quality target</span><input type=\"text\" name=\"qhost\" placeholder=\"gateway\"></label>\n"
"\n"
"      <div class=\"sub-h\">Bluetooth</div>\n"
"      <label class=\"fld\"><span>Bluetooth on</span><span class=\"sw\"><input type=\"checkbox\" name=\"ble\"><i></i></span></label>\n"
"      <label class=\"fld\"><span>Require PIN pairing (PIN shows on the tester)</span><span class=\"sw\"><input type=\"checkbox\" name=\"ble_pin\"><i></i></span></label>\n"
"      <label class=\"fld stack\"><span>Bluetooth GUI link (where you host ble.html, must be https://)</span><input type=\"url\" name=\"ble_url\" placeholder=\"https://yourname.github.io/netally-buster/ble.html\"></label>\n"
"      <div class=\"actions\"><button class=\"btn\" type=\"button\" id=\"b-bleforget\">Forget paired phones</button></div>\n"
"      <div class=\"actions\"><button class=\"btn go\" type=\"submit\">Save settings</button></div>\n"
"      <p class=\"note\" id=\"set-msg\">Turning the hotspot off from a phone that's on it will drop your connection.</p>\n"
"    </form>\n"
"    <div class=\"grid\">\n"
"      <div class=\"panel\">\n"
"        <h2>Restart and reset</h2>\n"
"        <p class=\"muted\">Factory reset clears every setting and the saved Wi-Fi network, then restarts.</p>\n"
"        <div class=\"actions\"><button class=\"btn\" id=\"b-reboot2\">Restart tester</button><button class=\"btn bad\" id=\"b-factory\">Factory reset</button></div>\n"
"      </div>\n"
"      <div class=\"panel\">\n"
"        <h2>Battery wiring</h2>\n"
"        <p class=\"muted\">1-cell Li-ion through a 100k/100k divider into GPIO4. Charger status (CHRG, active low) on GPIO5. Turn on \"Battery fitted\" once it's wired.</p>\n"
"      </div>\n"
"    </div>\n"
"  </div>\n"
"</section>\n"
"</main>\n"
"<div class=\"toast\" id=\"toast\"></div>\n"
"\n"
"<script>\n"
"const $=id=>document.getElementById(id);\n"
"const S={d:null,view:'port',tool:'ping',lastRuns:-1,prevSteps:[]};\n"
"const STEP=['Link','DHCP','Gateway','DNS','Internet','Switch'];\n"
"const ST=['','run','pass','warn','fail'];\n"
"\n"
"function txt(id,v){const e=$(id);if(e&&e.textContent!==String(v))e.textContent=v}\n"
"function dur(s){if(s<60)return s+'s';if(s<3600)return Math.floor(s/60)+'m '+(s%60)+'s';\n"
"  if(s<86400)return Math.floor(s/3600)+'h '+Math.floor(s%3600/60)+'m';return Math.floor(s/86400)+'d '+Math.floor(s%86400/3600)+'h'}\n"
"function cnt(n){return n<1e4?n:n<1e6?(n/1e3).toFixed(1)+'k':(n/1e6).toFixed(2)+'M'}\n"
"function toast(m){const t=$('toast');t.textContent=m;t.classList.add('show');clearTimeout(t._h);t._h=setTimeout(()=>t.classList.remove('show'),2200)}\n"
"function abbr(p){return (p||'').replace(/^TenGigabitEthernet/,'Te').replace(/^GigabitEthernet/,'Gi').replace(/^FastEthernet/,'Fa')}\n"
"async function post(u,body){try{const r=await fetch(u,{method:'POST',body});return r.ok}catch(e){return false}}\n"
"\n"
"\n"
"$('tabs').onclick=e=>{const b=e.target.closest('button');if(!b)return;\n"
"  showView(b.dataset.v);\n"
"if(S.view==='pkt')pollPkts();if(S.view==='dev')pollEvents();if(S.view==='swcfg')swPrefill();if(S.d)render(S.d)};\n"
"\n"
"\n"
"$('strip').innerHTML=STEP.map(n=>`<div class=\"seg\">${n}</div>`).join('');\n"
"$('t-steps').innerHTML=STEP.map((n,i)=>`<div class=\"step\" id=\"st${i}\"><div class=\"dot\"></div><div><div class=\"nm\">${n}</div><div class=\"inf\"></div></div><div class=\"val\"></div></div>`).join('');\n"
"function runTest(){post('/api/action?do=autotest');toast('AutoTest started')}\n"
"$('b-test').onclick=runTest;$('b-test2').onclick=runTest;\n"
"$('b-blink').onclick=()=>{post('/api/action?do=blink');toast('Blinking the port LED for 12 s')};\n"
"$('b-scan').onclick=()=>{post('/api/action?do=scan');toast('Scanning')};\n"
"$('b-reboot').onclick=()=>{if(confirm('Restart the tester?')){post('/api/action?do=reboot');toast('Restarting')}};\n"
"\n"
"\n"
"function canvas(id){const c=$(id),r=devicePixelRatio||1;if(!c._bh)c._bh=+c.getAttribute('height');const h=c._bh,w=c.clientWidth;\n"
"  if(c._w!==w){c._w=w;c.width=w*r;c.height=h*r;c.style.height=h+'px'}const x=c.getContext('2d');x.setTransform(r,0,0,r,0,0);x.clearRect(0,0,w,h);return[x,w,h]}\n"
"function line(id,arr,col,lo,hi){const[x,w,h]=canvas(id);if(!arr.length)return;\n"
"  lo=lo??Math.min(...arr);hi=hi??Math.max(...arr);if(hi-lo<1)hi=lo+1;\n"
"  const P=i=>[i*(w-2)/(arr.length-1)+1,h-4-(arr[i]-lo)/(hi-lo)*(h-10)];\n"
"  x.beginPath();arr.forEach((v,i)=>{const[a,b]=P(i);i?x.lineTo(a,b):x.moveTo(a,b)});\n"
"  x.strokeStyle=col;x.lineWidth=2;x.lineJoin='round';x.stroke();\n"
"  x.lineTo(w-1,h);x.lineTo(1,h);x.closePath();const g=x.createLinearGradient(0,0,0,h);g.addColorStop(0,col+'40');g.addColorStop(1,col+'00');x.fillStyle=g;x.fill()}\n"
"function chans(arr){const[x,w,h]=canvas('c-ch');const mx=Math.max(3,...arr),bw=w/13;\n"
"  arr.forEach((v,i)=>{const bh=(h-22)*v/mx,good=[0,5,10].includes(i);\n"
"    x.fillStyle=v?(good?'#5CD3F0':'#5C7189'):'#203449';x.fillRect(i*bw+3,h-18-Math.max(bh,2),bw-6,Math.max(bh,2));\n"
"    x.fillStyle='#8DA2B8';x.font='11px system-ui';x.textAlign='center';x.fillText(i+1,i*bw+bw/2,h-4)})}\n"
"\n"
"\n"
"const HINT={ping:['Host or IP, e.g. 8.8.8.8','Five pings, with min/avg/max and loss.'],\n"
" trace:['Host or IP, e.g. 1.1.1.1','Shows each router hop, up to 20.'],\n"
" dns:['Name, e.g. office.example.com','Asks the DNS server this port got from DHCP.'],\n"
" port:['host:port, e.g. 10.0.0.5:443','Tells you if a TCP port is open, closed or filtered.'],\n"
" sweep:['','Pings every address in this /24 and lists who answers.'],\n"
" scan:['Host or IP, e.g. 10.0.0.20','Checks 21 common TCP ports (SSH, RDP, SMB, printers, cameras...).'],\n"
" quality:['','100 pings to the gateway at 10 per second: loss, latency and jitter.'],\n"
" speed:['','HTTPS sample over Ethernet when connected, otherwise Wi-Fi. Results reflect the tester, TLS and network path.'],\n"
" wspeed:['','Wi-Fi only: bounded HTTPS download and 1 MB upload. No Ethernet fallback.'],\n"
" espeed:['','Ethernet only: bounded HTTPS download and 1 MB upload. No Wi-Fi fallback.'],\n"
" wol:['MAC, e.g. AA:BB:CC:DD:EE:FF','Sends a Wake-on-LAN magic packet on the local network.'],\n"
" secrouter:['','Checks your gateway for risky open admin services (Telnet, FTP, plain HTTP, remote management). Read-only.'],\n"
" secwifi:['','Rates nearby Wi-Fi: open networks, weak (WEP/old) encryption, and whether your own link is strong.'],\n"
" secdns:['','Checks that your DNS resolver answers honestly and does not redirect fake or non-existent names.'],\n"
" secarp:['','ARP inspection self-test: announces only this tester\\'s own address and reports whether the network lacks Dynamic ARP Inspection. It does not attack or impersonate anything.'],\n"
" secrogue:['','Checks nearby Wi-Fi for another radio broadcasting your SSID, or an open copy of it (evil twin).'],\n"
" secsnmp:['Optional target IP (default: switch/gateway)','Read-only: does the device still answer to the default SNMP communities public/private?'],\n"
" secupnp:['','Lists devices that answer UPnP/SSDP discovery and may open ports to the internet on their own.'],\n"
" sectls:['host or host:port (default: switch/gateway)','Checks an HTTPS service: trusted/self-signed cert, TLS version, and expiry date.'],\n"
" secdhcp:['','Shows how many DHCP servers are handing out leases on this wire (more than one = rogue DHCP).'],\n"
" secseg:['target IP on another VLAN (default: switch mgmt)','Tests whether something that should be isolated is reachable from this port.'],\n"
" buffer:['','Measures the extra latency to your gateway while the link is saturated (bufferbloat grade A-D).']};\n"
"$('tl-pick').onclick=e=>{const b=e.target.closest('button');if(!b)return;S.tool=b.dataset.t;\n"
"  document.querySelectorAll('#tl-pick button').forEach(x=>x.classList.toggle('on',x===b));\n"
"  $('tl-arg').placeholder=HINT[S.tool][0];$('tl-arg').disabled=!HINT[S.tool][0];txt('tl-hint',HINT[S.tool][1])};\n"
"$('tl-run').onclick=async()=>{const a=$('tl-arg').value.trim();\n"
"  if(HINT[S.tool][0]&&!a){$('tl-arg').focus();return}\n"
"  if(!await post(`/api/tool?type=${S.tool}&arg=${encodeURIComponent(a)}`))toast('A tool is already running');};\n"
"$('tl-arg').onkeydown=e=>{if(e.key==='Enter')$('tl-run').click()};\n"
"$('hs-refresh').onclick=loadHosts;\n"
"async function loadHosts(){try{const d=await (await fetch('/api/hosts')).json();\n"
"  txt('hs-count',d.n?`${d.n} found`:'');\n"
"  const h=d.list.map(x=>`<div class=\"row\"><span class=\"mono\">${x.ip}${x.name?'<br><span class=\"muted\">'+x.name+'</span>':''}</span><b class=\"mono\">${x.mac||'&mdash;'}${x.vendor?'<br><span class=\"muted\">'+x.vendor+'</span>':''}</b></div>`).join('');\n"
"  const el=$('hs-list'); if(el._v!==h){el.innerHTML=h||'<p class=\"muted\" style=\"padding:8px\">No devices yet. Tap Find hosts.</p>';el._v=h}}catch(e){}}\n"
"async function pollLog(){if(S.view!=='tools')return;try{const t=await (await fetch('/api/log')).text();\n"
"  const o=$('tl-out');if(t&&o.textContent!==t){const end=o.scrollTop+o.clientHeight>=o.scrollHeight-20;o.textContent=t;if(end)o.scrollTop=o.scrollHeight;\n"
"    if(/answered ping/.test(t))loadHosts();}}catch(e){}}\n"
"\n"
"\n"
"$('f-wifi').onsubmit=async e=>{e.preventDefault();const f=new URLSearchParams(new FormData(e.target));\n"
"  toast(await post('/api/wifi',f)?'Saved, connecting':'Could not save')};\n"
"$('w-aps').onclick=e=>{const r=e.target.closest('.ap');if(r&&r.dataset.s){$('f-ssid').value=r.dataset.s;$('f-ssid').scrollIntoView({behavior:'smooth',block:'center'})}};\n"
"\n"
"\n"
"function showView(v){S.view=v;document.querySelectorAll('.view').forEach(x=>x.classList.toggle('on',x.id==='v-'+v));\n"
"  document.querySelectorAll('#tabs button').forEach(x=>x.classList.toggle('on',x.dataset.v===v));\n"
"  $('b-gear').classList.toggle('on',v==='set');window.scrollTo(0,0)}\n"
"$('b-gear').onclick=()=>{showView('set');loadSettings()};\n"
"async function loadSettings(){try{const c=await (await fetch('/api/settings')).json();const f=$('f-set');\n"
"  for(const[k,v]of Object.entries(c)){const el=f.elements[k];if(!el)continue;\n"
"    if(el.type==='checkbox')el.checked=!!v;else if(el.tagName==='SELECT')el.value=String(typeof v==='boolean'?(v?1:0):v);else el.value=v}\n"
"  $('o-bright').textContent=f.elements.bright.value+'%';$('s-fields').hidden=!f.elements.static.checked}catch(e){toast('Could not load settings')}}\n"
"$('f-set').elements.bright.oninput=e=>$('o-bright').textContent=e.target.value+'%';\n"
"$('s-static').onchange=e=>$('s-fields').hidden=!e.target.checked;\n"
"$('f-set').onsubmit=async e=>{e.preventDefault();const f=e.target,p=new URLSearchParams();\n"
"  for(const el of f.elements){if(!el.name)continue;\n"
"    if(el.type==='checkbox')p.append(el.name,el.checked?'1':'0');\n"
"    else if(el.name==='ap_pass'&&el.value.length<8)continue; else p.append(el.name,el.value)}\n"
"  try{const r=await (await fetch('/api/settings',{method:'POST',body:p})).json();\n"
"    txt('set-msg',r.restart?'Saved. Restart the tester for the hotspot password, hub address or weather key to take effect.':'Saved.');toast('Settings saved')}\n"
"  catch(e){toast('Could not save')}};\n"
"$('b-reboot2').onclick=()=>{if(confirm('Restart the tester?')){post('/api/action?do=reboot');toast('Restarting')}};\n"
"$('b-bleforget').onclick=()=>{if(confirm('Unpair every phone from this tester? Each phone will need the PIN again.')){post('/api/action?do=bleforget');toast('Paired phones forgotten')}};\n"
"$('b-factory').onclick=()=>{if(confirm('Erase all settings and the saved Wi-Fi network?')){post('/api/action?do=factory');toast('Resetting')}};\n"
"\n"
"\n"
"$('b-qual').onclick=()=>{post('/api/action?do=quality');toast('Testing link quality (10 s)')};\n"
"$('b-speed').onclick=async()=>{toast(await post('/api/tool?type=espeed&arg=')?'Speed test running, see Tools':'A tool is already running')};\n"
"$('b-renew').onclick=()=>{post('/api/action?do=renew');toast('Renewing DHCP lease')};\n"
"$('b-copy').onclick=async()=>{try{const t=await (await fetch('/api/report')).text();\n"
"  const ta=document.createElement('textarea');ta.value=t;document.body.appendChild(ta);ta.select();\n"
"  let ok=false;try{ok=document.execCommand('copy')}catch(e){}\n"
"  if(!ok&&navigator.clipboard)try{await navigator.clipboard.writeText(t);ok=true}catch(e){}\n"
"  ta.remove();toast(ok?'Report copied':'Copy blocked, use Open report')}catch(e){toast('Could not build report')}};\n"
"\n"
"\n"
"S.kPause=false;\n"
"$('k-pause').onclick=e=>{S.kPause=!S.kPause;e.target.textContent=S.kPause?'Resume':'Pause'};\n"
"const KB=[['IPv4','#5CD3F0'],['IPv6','#A88BFA'],['ARP','#F2B84B'],['L2 control','#FB923C'],['Other','#5C7189']];\n"
"async function pollPkts(){if(S.view!=='pkt')return;try{const k=await (await fetch('/api/packets')).json();\n"
"  const P=k.pk,v=[P.IPv4,P.IPv6,P.ARP,P.LLDP+P.CDP+P.STP,P.Other],tot=v.reduce((a,b)=>a+b,0)||1;\n"
"  txt('k-tot',`${k.fps} frames/s, ${cnt(k.total)} seen`);\n"
"  if(!$('k-bars').children.length)$('k-bars').innerHTML=KB.map(b=>`<div class=\"pbar\"><span>${b[0]}</span><div class=\"tr\"><i style=\"background:${b[1]};width:0\"></i></div><b>0%</b></div>`).join('');\n"
"  [...$('k-bars').children].forEach((r,i)=>{const p=Math.round(v[i]*100/tot);r.querySelector('i').style.width=p+'%';r.querySelector('b').textContent=p+'%'});\n"
"  const apps=['TCP','UDP','ICMP','IGMP','DHCP','DNS','mDNS','SSDP','NetBIOS','LLMNR','NTP','SNMP','802.1Q','STP','LLDP','CDP'];\n"
"  const ah=apps.map(a=>`<span class=\"chip\">${a}<b>${cnt(P[a]||0)}</b></span>`).join('');if($('k-apps')._v!==ah){$('k-apps').innerHTML=ah;$('k-apps')._v=ah}\n"
"  const th=k.talkers.map(x=>`<div class=\"row\"><span class=\"mono\">${x.ip||x.m}${x.me?' <span class=\"muted\">(this tester)</span>':''}<br><span class=\"muted\">${x.ip?x.m:''}</span></span><b>${cnt(x.f)} frames<br><span class=\"muted\">${x.bc?cnt(x.bc)+' broadcast':''}</span></b></div>`).join('');\n"
"  if(th&&$('k-talk')._v!==th){$('k-talk').innerHTML=th;$('k-talk')._v=th}\n"
"  if(!S.kPause){txt('k-live',`last ${k.frames.length}`);\n"
"    $('k-list').innerHTML=k.frames.map(f=>`<div class=\"pk ${f.p}\"><span class=\"pt\">${f.t}</span><span class=\"pp\">${f.p}</span><span class=\"pi\">${(f.i||'').replace(/</g,'&lt;')||f.l+' bytes'}</span><span class=\"ps\">${f.s} → ${f.d}  ${f.l} B</span></div>`).join('')||'<p class=\"muted\" style=\"padding:10px\">No frames yet.</p>'}\n"
"}catch(e){}}\n"
"setInterval(pollPkts,1500);\n"
"\n"
"\n"
"async function pollEvents(){if(S.view!=='dev')return;try{const ev=await (await fetch('/api/events')).json();\n"
"  const h=ev.map(e=>`<div class=\"row\"><span>${e.t||dur(e.up)+' after boot'}</span><b>${e.m.replace(/</g,'&lt;')}</b></div>`).join('');\n"
"  if(h&&$('d-events')._v!==h){$('d-events').innerHTML=h;$('d-events')._v=h}}catch(e){}}\n"
"setInterval(pollEvents,4000);\n"
"\n"
"\n"
"$('b-wspeed').onclick=async()=>toast(await post('/api/tool?type=wspeed&arg=')?'Wi-Fi speed test started':'A tool is already running');\n"
"$('b-speedstop').onclick=()=>post('/api/action?do=speedstop');\n"
"$('wire-quality').onclick=()=>post('/api/action?do=quality');\n"
"function renderDiagnostics(d){\n"
" const W=d.wifi,R=d.wifi_speed,P=d.poe,D=d.dev,L=d.link,Q=d.quality;\n"
" document.documentElement.style.setProperty('--text-scale',D.text_size?'1.18':'1');\n"
" document.body.classList.toggle('high-contrast',D.contrast);\n"
" document.body.classList.toggle('reduced-motion',!D.animations);\n"
" const c=(id,v)=>txt(id,W.conn?v:'--');\n"
" c('wi-radio',`${W.frequency} MHz / ${W.width} MHz`);c('wi-secondary',W.secondary===1?'Above primary':W.secondary===-1?'Below primary':'None');\n"
" c('wi-cipher',`${W.pairwise} / ${W.group}`);c('wi-mask',W.mask);c('wi-gw',W.gw);c('wi-dns',W.dns);\n"
" txt('wi-mac',W.mac||'--');c('wi-up',dur(W.up_s));txt('wi-disc',`${W.reconnects} / ${W.disconnect_reason||'none'}`);\n"
" c('wi-country',`${W.country||'unset'} / ${W.powersave?'on':'off'}`);txt('wi-scan',W.scan_age>=0?dur(W.scan_age)+' ago':'No scan');\n"
" txt('ws-stage',R.stage||'Not run');txt('ws-down',R.down_ok?R.down.toFixed(2):'--');txt('ws-up',R.up_ok?R.up.toFixed(2):'--');\n"
" txt('ws-first',R.down_ok?R.first_byte+' ms':'--');txt('ws-network',R.network?R.network+(R.channel?' · ch '+R.channel:''):'--');\n"
" txt('ws-bytes',`${(R.down_bytes/1e6).toFixed(2)} MB down / ${(R.up_bytes/1e6).toFixed(2)} MB up`);\n"
" txt('ws-age',R.age>=0?dur(R.age)+' ago':'--');txt('ws-error',R.error||'');\n"
" $('ws-bar').style.width=(R.running?R.progress:R.down_ok?100:0)+'%';$('ws-progress').setAttribute('aria-valuenow',R.progress);\n"
" $('b-wspeed').disabled=d.tool||!W.conn||W.scanning;$('b-speedstop').disabled=!R.running&&!d.eth_speedtest.running;\n"
" txt('wire-link',L.link?`${L.speed} Mb/s ${L.full?'full':'half'} duplex`:'No link');$('wire-quality').disabled=!L.ip_ok||Q.running;\n"
" txt('wire-quality-result',Q.running?`Testing ${Q.done}%`:Q.sent?`${Q.recv}/${Q.sent} replies · average ${Q.avg} ms · jitter ${Q.jitter} ms`:'No link-quality test yet');\n"
" const fresh=P.fresh,w=v=>fresh&&v>=0?(v/1000).toFixed(1)+' W':'Not reported',v=(id,x)=>txt(id,fresh?x:'--');\n"
" txt('po-status',fresh?'Fresh advertisement':P.advertised?'Old / disconnected':'Not advertised');\n"
" v('po-proto',P.protocol);v('po-role',P.mdi?(P.pse?'PSE · power source':'PD · powered device'):'Not reported');\n"
" v('po-enable',P.mdi?`${P.supported?'Yes':'No'} / ${P.enabled?'Yes':'No'}`:'Not reported');\n"
" v('po-class',`${P.class>=0?'Class '+P.class:'Not reported'}${P.extended?' / Type '+P.type:''}`);\n"
" v('po-pairs',P.mdi?`${P.pairs===1?'1–2 / 3–6 · data':P.pairs===2?'4–5 / 7–8 · spare':'Not reported'} / control ${P.pair_control?'yes':'no'}`:'Not reported');\n"
" v('po-priority',P.priority>=0&&P.priority<=3?['Unknown','Critical','High','Low'][P.priority]:'Not reported');\n"
" txt('po-request',w(P.requested_mw));txt('po-allocate',w(P.allocated_mw));txt('po-med',w(P.med_mw));\n"
" v('po-cdp',w(P.available_mw)+' / '+w(P.used_mw));txt('po-age',P.advertised?dur(P.age)+' ago':'--');\n"
" $('b-speed').disabled=d.tool||!L.ip_ok;\n"
"}\n"
"\n"
"\n"
"function led(id,on,mid){const e=$(id);e.classList.toggle('on',!!on);e.classList.toggle('mid',!on&&!!mid)}\n"
"function render(d){\n"
"  renderDiagnostics(d);\n"
"  const L=d.link,W=d.wifi,SW=d.switch,T=d.test,D=d.dev;\n"
"  led('l-eth',L.ip_ok,L.link);led('l-wifi',W.conn);led('l-bt',D.ble_conn);\n"
"  const B=d.batt,lb=$('l-batt');lb.hidden=!B.enabled;\n"
"  if(B.enabled){lb.className='led batt '+(!B.present?'':B.charging?'chg':B.pct<=15?'low':'ok');txt('l-batt-t',B.present?B.pct+'%':'--')}\n"
"\n"
"\n"
"  const A=d.alerts;txt('al-count',A.list.length?(A.bad?A.bad+' to check':'info only'):'');\n"
"  const ah=A.list.map(a=>`<div class=\"al l${a.l}\"><b>${a.l==2?'Problem':a.l==1?'Check':'Info'}</b><span>${a.t.replace(/</g,'&lt;')}</span></div>`).join('')||'<p class=\"clear\">Nothing wrong spotted on this port.</p>';\n"
"  if($('al-list')._v!==ah){$('al-list').innerHTML=ah;$('al-list')._v=ah}\n"
"\n"
"\n"
"  const hp=$('h-port');\n"
"  if(SW.found){hp.className='port';txt('h-port',abbr(SW.port));txt('h-where',SW.name)}\n"
"  else if(L.link){hp.className='port idle';txt('h-port',L.ip_ok?'Listening for the switch':'Waiting for DHCP');txt('h-where',L.ip_ok?'LLDP / CDP can take up to a minute':'Link is up')}\n"
"  else{hp.className='port idle';txt('h-port','No link');txt('h-where','Plug the tester into a wall jack or switch port')}\n"
"  const f=[];if(SW.found&&SW.vlan)f.push(`VLAN <b>${SW.vlan}</b>`);if(SW.voice)f.push(`Voice <b>${SW.voice}</b>`);\n"
"  if(L.link)f.push(`<b>${L.speed} Mb/s</b> ${L.full?'full':'half'} duplex`);if(L.ip_ok)f.push(`<b class=\"mono\">${L.ip}</b>`);\n"
"  if(SW.poe)f.push(`PoE <b>${SW.poe}</b>`);\n"
"  const fh=f.join('');if($('h-facts')._v!==fh){$('h-facts').innerHTML=f.map(x=>`<span>${x}</span>`).join('');$('h-facts')._v=fh}\n"
"  $('b-blink').disabled=L.blink||!L.link;$('b-blink').textContent=L.blink?'Blinking…':'Blink port LED';\n"
"\n"
"\n"
"  const segs=$('strip').children;\n"
"  T.steps.forEach((s,i)=>{const c=ST[s.s];const seg=segs[i];\n"
"    if(seg.dataset.c!==c){seg.className='seg '+c;seg.dataset.c=c;\n"
"      if(c==='pass'||c==='warn'||c==='fail'){seg.classList.add('pop');setTimeout(()=>seg.classList.remove('pop'),350)}}\n"
"    const row=$('st'+i);row.className='step '+c;row.querySelector('.val').textContent=s.v||'';row.querySelector('.inf').textContent=s.i||''});\n"
"  ['b-test','b-test2'].forEach(id=>{$(id).disabled=T.running;$(id).textContent=T.running?'Testing…':(T.runs?'Run again':'Run AutoTest')});\n"
"  txt('t-sum',T.running?'running':T.result===1?'all passed':T.result===2?'passed with warnings':T.result===3?'problems found':'not run yet');\n"
"  if(S.lastRuns>=0&&!T.running&&S.wasRunning)toast(T.result===1?'AutoTest passed':T.result===2?'AutoTest: warnings':'AutoTest found problems');\n"
"  S.wasRunning=T.running;S.lastRuns=T.runs;\n"
"\n"
"  if(S.view==='port'){\n"
"    txt('p-rate',`${L.fps} frames/s, ${cnt(L.bps)}B/s`);line('c-fps',d.fps,'#5CD3F0',0);\n"
"    txt('p-bcmc',`${L.bc}% / ${L.mc}%`);txt('p-rx',cnt(L.rx));txt('p-arp',cnt(L.rx_arp));\n"
"    txt('p-up',L.link?dur(L.up_s):'down');txt('p-flaps',L.flaps);\n"
"    txt('s-proto',SW.found?SW.proto:(L.link?'listening':''));\n"
"    const sv=(id,v)=>txt(id,v||'--');\n"
"    sv('s-name',SW.found&&SW.name);sv('s-port',SW.found&&SW.port);sv('s-pdesc',SW.found&&SW.pdesc);sv('s-vlan',SW.found&&SW.vlan);\n"
"    txt('s-voice',SW.found?(SW.voice||'none'):'--');sv('s-mode',SW.found&&SW.mode);sv('s-mgmt',SW.found&&SW.mgmt);\n"
"    sv('s-model',SW.found&&SW.model);sv('s-ver',SW.found&&SW.ver);sv('s-caps',SW.found&&SW.caps);sv('s-duplex',SW.found&&SW.duplex);sv('s-poe',SW.found&&SW.poe);\n"
"    txt('s-stp',SW.stp?SW.stp_root+(SW.stp_tc?'  (topology change)':''):'no BPDUs heard');\n"
"    txt('s-age',SW.found?`${dur(SW.age)} ago`:'--');\n"
"    const Q=d.quality;\n"
"    const mm=SW.duplex&&((/Full/.test(SW.duplex)&&!L.full)||(/Half/.test(SW.duplex)&&L.full));\n"
"    const loss=Q.sent?Math.round((Q.sent-Q.recv)*100/Q.sent):0;\n"
"    const v=!L.hw?'no Ethernet chip':!L.link?'no link':mm?'duplex mismatch':(L.speed==10||!L.full)?'slow link':(Q.sent&&loss>1)?'packet loss':'looks good';\n"
"    txt('c-verdict',v);$('c-verdict').style.color=v==='looks good'?'var(--pass)':(v==='no link'||mm)?'var(--fail)':'var(--warn)';\n"
"    txt('c-me',L.link?`${L.speed} Mb/s ${L.full?'full':'half'} duplex`:'no link');txt('c-sw',SW.duplex||'not reported');\n"
"    txt('c-can',SW.adv?SW.adv+' Mb/s':'not reported');\n"
"    txt('c-drops',`${L.flaps} total`);\n"
"    txt('c-loss',Q.running?`testing… ${Q.done}%`:Q.sent?`${loss}% (${Q.recv}/${Q.sent} to ${Q.target})`:'not tested');\n"
"    txt('c-lat',Q.recv?`${Q.avg} ms avg, ${Q.max} ms max, ${Q.jitter} ms jitter`:'--');\n"
"    txt('c-speed',d.eth_speedtest.down_ok?d.eth_speedtest.down.toFixed(2)+' Mbit/s':'not tested');\n"
"    $('b-qual').disabled=Q.running||!L.ip_ok;$('b-qual').textContent=Q.running?'Testing…':'Test link quality';\n"
"    $('b-renew').disabled=!L.link||L.static;\n"
"    const ip=v=>L.ip_ok?v:'--';txt('i-ip',ip(L.ip));txt('i-mask',ip(L.mask));txt('i-gw',ip(L.gw));txt('i-dns',ip(L.dns));\n"
"    txt('i-dhcp',L.ip_ok?`${L.dhcp} (${(L.dhcp_ms/1000).toFixed(1)} s)`:'--');txt('i-lease',L.lease?dur(L.lease):'--');txt('i-mac',L.mac);\n"
"  }\n"
"  if(S.view==='wifi'){\n"
"    if(W.conn){txt('w-rssi',W.rssi);txt('w-q',W.rssi>=-55?'excellent':W.rssi>=-67?'good':W.rssi>=-75?'fair':'weak');\n"
"      txt('w-ssid',W.ssid);txt('w-bssid',W.bssid);txt('w-ch',W.ch);txt('w-sec',`${W.auth}, ${W.phy}`);txt('w-ip',W.ip)}\n"
"    else{txt('w-rssi','--');txt('w-q',W.cfg?'connecting to '+W.cfg:'not set up');['w-ssid','w-bssid','w-ch','w-sec','w-ip'].forEach(i=>txt(i,'--'))}\n"
"    line('c-rssi',d.rssi,'#57D68D',-100,-30);\n"
"    txt('w-count',W.scanning?'scanning…':W.count?W.count+' found':'');\n"
"    const h=W.aps.map(a=>{const n=a.r>=-55?4:a.r>=-67?3:a.r>=-75?2:1,col=n>=3?'#57D68D':n==2?'#F2B84B':'#F0625D';\n"
"      return `<div class=\"ap\" data-s=\"${a.s.replace(/\"/g,'&quot;')}\"><div class=\"bars\">${[1,2,3,4].map(k=>`<i style=\"${k<=n?'background:'+col:''}\"></i>`).join('')}</div>\n"
"      <div><div>${a.s?a.s.replace(/</g,'&lt;'):'<span class=\"muted\">hidden network</span>'}</div><div class=\"sub mono\">${a.b}</div></div>\n"
"      <div style=\"text-align:right\"><div>${a.r} dBm</div><div class=\"sub ${a.a==='OPEN'?'open':''}\">ch ${a.c}, ${a.a.toLowerCase()==='open'?'open':a.a}</div></div></div>`}).join('');\n"
"    if($('w-aps')._v!==h){$('w-aps').innerHTML=h||'<p class=\"muted\">No networks heard. Tap Scan again.</p>';$('w-aps')._v=h}\n"
"    chans(W.chans);const c=[1,6,11].sort((a,b)=>W.chans[a-1]-W.chans[b-1])[0];txt('w-best',W.count?`quietest: channel ${c}`:'');\n"
"  }\n"
"  if(S.view==='tools')txt('tl-state',d.tool?(d.sweep?`probing ${d.sweep_done}/254, ${d.sweep_found} found`:'running…'):'');\n"
"  if(S.view==='dev'){\n"
"    txt('d-up',dur(D.up));txt('d-chip',D.units_c?((D.chip_f-32)*5/9).toFixed(1)+' °C':D.chip_f.toFixed(1)+' °F');txt('d-heap',`${Math.round(D.heap/1024)} KB (lowest ${Math.round(D.heap_min/1024)} KB)`);\n"
"    txt('d-fw','v'+D.fw);txt('d-batt',!B.enabled?'not fitted (Settings)':!B.present?'no reading on GPIO4':`${B.pct}%, ${B.v.toFixed(2)} V${B.charging?', charging':''}`);txt('d-rst',D.reset);txt('d-ble',(D.ble_conn?(D.ble_secure?'phone paired, encrypted':'phone connected'):D.ble?`advertising as \"${D.ble_name}\"`:'off')+(D.ble_bonds?` · ${D.ble_bonds} paired`:''));\n"
"    txt('d-ap',`${d.gui.ssid}, ${D.ap_clients} connected`);txt('d-mqtt',D.mqtt?'connected':'not connected');\n"
"    txt('d-wx',D.wx?`${D.wx_temp} °F, ${D.wx_cond}`:'no weather key set');\n"
"    const u=[['Hotspot',d.gui.url,`${d.gui.ssid} / ${d.gui.pass}`],['Ethernet',d.gui.eth_url],['Wi-Fi',d.gui.wifi_url]].filter(x=>x[1]);\n"
"    const h=u.map(x=>`<div class=\"row\"><span>${x[0]}</span><b class=\"mono\">${x[1]}${x[2]?'<br><span class=\"muted\">'+x[2]+'</span>':''}</b></div>`).join('');\n"
"    if($('d-urls')._v!==h){$('d-urls').innerHTML=h;$('d-urls')._v=h}\n"
"  }\n"
"}\n"
"\n"
"\n"
"\n"
"function swPrefill(){const d=S.d;if(!d)return;\n"
"  if(!$('sw-host').value&&d.switch&&d.switch.mgmt)$('sw-host').value=d.switch.mgmt;\n"
"  if(!$('sw-port').value&&d.switch&&d.switch.port)$('sw-port').value=(d.switch.port.match(/[0-9]+\\/[0-9]+\\/[0-9]+|[0-9]+\\/[0-9]+/)||[d.switch.port])[0];\n"
"  swRefresh();}\n"
"let swPoll=null;\n"
"function swShow(d){\n"
"  txt('sw-status',d.status||'Not connected.');\n"
"  const vb=$('sw-vlanbox');\n"
"  if(d.connected&&d.vlans&&d.vlans.length){\n"
"    vb.hidden=false;\n"
"    const sel=$('sw-vlan');\n"
"    if(sel._v!==d.vlans.join(',')){sel.innerHTML=d.vlans.map(v=>`<option value=\"${v}\">VLAN ${v}</option>`).join('');sel._v=d.vlans.join(',')}\n"
"    txt('sw-cur',d.cur?`Port ${d.port} is currently on VLAN ${d.cur}.`:`Port ${d.port||'(set above)'}.`);\n"
"    swPreview();\n"
"  }\n"
"  if(d.result){$('sw-outbox').hidden=false;const o=$('sw-out');if(o.textContent!==d.result)o.textContent=d.result}\n"
"  const busy=d.busy;\n"
"  $('sw-connect').disabled=busy;$('sw-apply').disabled=busy;\n"
"  if(!busy&&swPoll){clearInterval(swPoll);swPoll=null}\n"
"}\n"
"function swPreview(){const v=$('sw-vlan').value,port=$('sw-port').value.trim();\n"
"  $('sw-preview').textContent=v&&port?`conf t\\n vlan ${v}\\n  untagged ethernet ${port}\\nend\\nwrite memory`:'Pick a VLAN.'}\n"
"$('sw-vlan')&&($('sw-vlan').onchange=swPreview);\n"
"async function swRefresh(){try{swShow(await (await fetch('/api/switch')).json())}catch(e){}}\n"
"$('f-sw').onsubmit=async e=>{e.preventDefault();\n"
"  const f=new URLSearchParams(new FormData(e.target));\n"
"  if(!await post('/api/switch/connect',f)){toast('Connect failed');return}\n"
"  toast('Connecting over SSH...');$('sw-outbox').hidden=true;\n"
"  if(swPoll)clearInterval(swPoll);swPoll=setInterval(swRefresh,1200);swRefresh();};\n"
"$('sw-apply').onclick=async()=>{\n"
"  const v=$('sw-vlan').value,port=$('sw-port').value.trim();\n"
"  if(!v||!port){toast('Pick a VLAN and port');return}\n"
"  if(!confirm(`Apply to ${$('sw-host').value}\\n\\nMove port ${port} to VLAN ${v}?\\n\\nThis changes live switch config.`))return;\n"
"  const p=new URLSearchParams();['host','user','pass','port'].forEach(k=>p.append(k,$('f-sw').elements[k].value));p.append('vlan',v);\n"
"  if(!await post('/api/switch/apply',p)){toast('Apply failed');return}\n"
"  toast('Applying...');if(swPoll)clearInterval(swPoll);swPoll=setInterval(swRefresh,1200);swRefresh();};\n"
"\n"
"\n"
"async function poll(){\n"
"  try{const r=await fetch('/api/status',{cache:'no-store'});S.d=await r.json();render(S.d);$('top').classList.remove('stale')}\n"
"  catch(e){$('top').classList.add('stale')}\n"
"  pollLog();\n"
"  setTimeout(poll,document.hidden?4000:1000);\n"
"}\n"
"poll();\n"
"addEventListener('resize',()=>S.d&&render(S.d));\n"
"</script>\n"
"</body>\n"
"</html>\n";
